def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Fill a horizontal 5-bar from the colored sequence below its left end.
    for r in range(h):
        cols = [c for c, value in enumerate(g[r]) if value == 5]
        if not cols:
            continue
        segments = []
        start = previous = cols[0]
        for c in cols[1:]:
            if c != previous + 1:
                segments.append((start, previous))
                start = c
            previous = c
        segments.append((start, previous))
        for left, right in segments:
            if r + 1 < h and all(g[r + 1][c] != 5 for c in range(left, right + 1)):
                seed_rows = [rr for rr in range(r + 1, h) if g[rr][left] not in (0, 5)]
                seed = [g[rr][left] for rr in seed_rows]
                for i, rr in enumerate(seed_rows):
                    for c in range(left, right + 1):
                        if g[rr][c] == 0:
                            g[rr][c] = seed[i % len(seed)]
    # Extend the tile immediately to the right of a vertical 5-bar upward.
    for c in range(w):
        rows = [r for r in range(h) if g[r][c] == 5]
        if not rows:
            continue
        segments = []
        start = previous = rows[0]
        for r in rows[1:]:
            if r != previous + 1:
                segments.append((start, previous))
                start = r
            previous = r
        segments.append((start, previous))
        for top, bottom in segments:
            right_cols = [cc for cc in range(c + 1, w)
                          if any(g[r][cc] not in (0, 5) for r in range(max(top, bottom - 3), bottom + 1))]
            if not right_cols:
                continue
            data_rows = [r for r in range(max(top, bottom - 3), bottom + 1)
                         if any(g[r][cc] not in (0, 5) for cc in right_cols)]
            if not data_rows:
                continue
            patterns = [[g[r][cc] for cc in right_cols] for r in data_rows]
            for r in range(top, bottom + 1):
                pattern = patterns[(r - top) % len(patterns)]
                for j, cc in enumerate(right_cols):
                    if g[r][cc] == 0:
                        g[r][cc] = pattern[j]
    return g
